#!/usr/bin/env python3
"""Run tools/levels.py and write the JS level module used by the game."""
from pathlib import Path
import subprocess
import sys

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "src" / "levels.js"

text = subprocess.check_output([sys.executable, str(ROOT / "tools" / "levels.py")], text=True)
start = text.index("  {")
end = text.rindex("  },") + len("  },")
body = text[start:end]
js = (
    "/* Boulder Dash levels — generated by tools/levels.py, hand-tuned. */\n"
    "const LEVELS = [\n" + body + "\n];\n"
)
OUT.write_text(js, encoding="utf-8")
print(f"updated {OUT.relative_to(ROOT)} · {len(body.splitlines())} lines")
